{"command": "cd /workspace && cat > work/fxprobe.py <<'EOF'
import numpy as np, base64, json, subprocess
R=8363.0
NCH=14
freqs=[180.0+i*40.0 for i in range(NCH)]
calls=[{"name":"module_new","arguments":{"channels":NCH+2,"name":"FXPROBE"}}]
def mk_sine(f):
    cyc=max(1,int(round(4096.0/(R/f))))
    n=int(round(cyc*R/f))
    t=np.arange(n)/R
    return np.sin(2*np.pi*f*t).astype(np.float32)
for i in range(NCH):
    if i==9:
        rs=np.random.RandomState(7); n=4096
        s=rs.uniform(-1,1,n).astype(np.float32)
    else:
        s=mk_sine(freqs[i])
    calls.append({"name":"sample_create_from_pcm","arguments":{"instrument":i+1,"sample":0,"pcm":base64.b64encode(s.tobytes()).decode(),"encoding":"float32","name":"s%d"%i}})
    calls.append({"name":"sample_set","arguments":{"instrument":i+1,"sample":0,"relative_note":0,"finetune":0,"volume":64,"loop_start":0,"loop_length":len(s),"flags":16}})
    calls.append({"name":"instrument_set","arguments":{"instrument":i+1,"name":"I%d"%i}})
calls.append({"name":"song_set","arguments":{"bpm":125,"speed":6,"length":1,"loop_start":0}})
def put(row,ch,note=None,ins=None,vol=None,fx=None,fxp=None):
    a={"pattern":0,"row":row,"channel":ch}
    for k,v in (('note',note),('instrument',ins),('volume',vol),('effect',fx),('effect_param',fxp)):
        if v is not None: a[k]=v
    calls.append({"name":"pattern_set_cell","arguments":a})
tests=[
 (0x00,0x47,'arp'),(0x0A,0x04,'vsl_down'),(0x0A,0x40,'vsl_up'),(0x04,0x64,'vibrato'),
 (0x07,0x64,'tremolo'),(0x0E,0x92,'retrig'),(0x0E,0xC4,'notecut'),(0x0E,0xD4,'notedelay'),
 (0x01,0x08,'porta_up'),(0x09,0x40,'offset'),(0x0C,0x10,'setvol'),(0x08,0x40,'panning'),
 (None,None,'volcol10'),(None,None,'ref'),
]
for ch,(fx,fxp,nm) in enumerate(tests):
    if nm=='volcol10':
        put(0,ch,'C-4',ch+1,vol=0x10)
    elif nm=='setvol':
        put(0,ch,'C-4',ch+1,fx=0x0C,fxp=0x10)
    else:
        put(0,ch,'C-4',ch+1,fx=fx,fxp=fxp)
    if nm=='porta_up':
        for r in range(1,24): put(r,ch,None,None,None,0x01,0x08)
calls.append({"name":"module_save","arguments":{"path":"work/fxp.xm","format":"xm"}})
calls.append({"name":"module_render","arguments":{"path":"work/fxp.wav","rate":44100,"bits":16,"amp":16,"loops":1}})
open('work/fxp.json','w').write(json.dumps(calls))
json.dump({'freqs':freqs,'names':[t[2] for t in tests]},open('work/fxp_meta.json','w'))
