        txt="\n".join(x.get("text","") for x in res.get("content",[]) if x.get("type")=="text")
        if res.get("isError"): raise RuntimeError(txt)
        return txt
    def close(self):
        try:
            self.p.stdin.close(); self.p.wait(timeout=3)
        except Exception: self.p.kill()
